mapper.select:
SELECT allocate_id as allocateId, allocate_code as allocateCode, outbound_organization_id as outboundOrganizationId, warehousing_organization_id as warehousingOrganizationId, `status` as status, add_by as addBy, DATE_FORMAT(FROM_UNIXTIME(add_time), '%Y-%m-%d %H:%i:%s') as addTime, stock_in_comment as stockInComment, stock_out_comment as stockOutComment, stock_allocate_comment as comment FROM product_stock_allocate_record
AND (outbound_organization_id = #{productStockAllocateRecordDTO.shopId} OR warehousing_organization_id = #{productStockAllocateRecordDTO.shopId})
AND (allocate_code LIKE CONCAT('%',#{productStockAllocateRecordDTO.keyword},'%'))
AND `status` = #{productStockAllocateRecordDTO.status}
AND add_by = #{productStockAllocateRecordDTO.addBy}
ORDER BY add_time DESC

SELECT pr.allocate_code, pr.outbound_organization_id, pr.warehousing_organization_id, pr.`status`, pr.add_by, pr.add_time FROM product_stock_allocate_record pr where (pr.warehousing_organization_id = #{shopId} or pr.outbound_organization_id = #{shopId})
AND pr.allocate_id IN
#{allocateId}
